    '#ywhy_shimaige:die': '卑鄙的霍比特人……偷走了我的宝贝……<br><br><br>',
    '#ywhy_moxing1': '咕噜……咕噜……',
    '#ywhy_moxing2': 'My Precious！',
    '#ywhy_moxing3': '[胆小人格]他们咒骂我们，说我们是杀人凶手！',
    '#ywhy_tantie1': '[胆小人格]小偷巴金斯！我们恨他，我们永远都恨他！',
    '#ywhy_tantie2': '[邪恶人格]坏人伤害我们！主人欺负我们！杀了他！杀了他！',
    '#ywhy_tantie3': '[邪恶人格]丑陋的霍比特人，偷走了我们的宝贝儿！',
    '#ywhy_shengdan1': '[邪恶人格]可怜的小霍比特人，要被巨蛛希洛布生吞啦！',
    '#ywhy_shengdan2': '[邪恶人格]池塘的鱼儿好甘甜……',
    '#ywhy_gulu:die': '[双人格]我们好孤单，哭得好惨……<br><br><br>',
    '#sdyx_renshu1': '药到病除，效如桴鼓[fú gǔ]！',
