    '#sdyx_lingluo4': '午夜梦回惊坐起，风吹落红入寒窗！',
    '#sdyx_yiqu1': '此夜曲中奏潮水，何人不起伤怀情。',
    '#sdyx_yiqu2': '我抚玉箫已叹息，又舞桃花复凄凄！',
    '#sdyx_yiqu3': '广陵绝响何人继？碧海潮生一夜箫！',
    '#sdyx_yiqu4': '桃花飞殇哀往事，曲尽碧海尚彷徨！',
    '#sdyx_wumianfeng:die': '一别数载，桃花依旧……<br><br><br>',
    '#ywhy_lianti1': '我们的身体紧密相连，我们的灵魂自由无边！',
    '#ywhy_lianti2': '在这四分五裂的世界，我们，是最完美的统一！',
