    '#ywhy_lianti4': '我们，绝不会让任何人定义我们！',
    '#ywhy_masheng1': '我们的生命与故事，由我们自己来书写！',
    '#ywhy_masheng2': '我们是姐妹，我们亦是战士！',
    '#ywhy_masheng3': '敢伤害我们其中一个，就是与我们两个为敌！',
    '#ywhy_lixin1': '我们共享生命、共享痛苦，也共享复仇的怒火！',
    '#ywhy_lixin2': '我们不可分割，任何试图拆散我们的，都将付出代价！',
    '#ywhy_beiteduote:die': '死亡让我们分离，但我们的灵魂，将永远相依……<br><br><br>',
    '#tlbb_haodou1': '[嗅探]有血腥气！前面八成有人打架！',
    '#tlbb_haodou2': '今天这一架，打得痛快至极！',
    '#tlbb_haodou3': '想打架吗？风某，随时奉陪！',
    '#tlbb_haodou4': '好啊！今天找到个好对手！',
