    '#tlbb_chandou3': '何人最好斗？江南一阵风！',
    '#tlbb_fengboe:die': '唉，技不如人，今后再也不好斗了……<br><br><br>',
    '#yttl_hunyuan1': '混元心法，精锐持修！',
