    '#tlbb_qianzhu2': '姑苏慕容氏，你我不共戴天！',
    '#tlbb_cuibaiquan:die': '千算万算，人心难算……<br><br><br>',
    '#tlbb_shihua1': '泪眼问花花不语，风吹红乱乱我心。',
