    '#tlbb_yihui1': '阆苑花发处，人间葬红时！',
    '#tlbb_yihui2': '南国有名种，春时寄相思！',
    '#tlbb_shiqinglu:die': '人非花是花睹人，花是人非人无花……<br><br><br>',
    '#tlbb_pudu1': '渡海发慈心，誓愿救万民！',
