    '#tlbb_zaizhang1': '身染疾恙，亦不可移我之志！',
    '#tlbb_zaizhang2': '奇木异树，可治瘴毒！',
    '#tlbb_tashu1': '乔帮主，你本姓是萧，你可知否？',
    '#tlbb_tashu2': '石刻虽能抹，罪业不可销！',
    '#tlbb_zhiguangdashi:die': '恩怨是非，俱作尘土……<br><br><br>',
    '#tlbb_yanbing1': '陛下此生，永不犯宋。若违此誓，有如此箭！',
    '#tlbb_yanbing2': '单于断箭英雄去，月下犹闻燕赵歌。',
