    '#tlbb_yixin_new2': '事关宋辽两国杀伐，汝当守口如瓶！',
    '#tlbb_wangjiantong:die': '胡汉恩仇英雄泪，雁门边声葬忠魂……<br><br><br>',
    '#tlbb_fudu_new1': '这生死符，犹如附骨之疽！',
