    '#tlbb_lvdao_new2': '香露初凝，剧毒封喉！',
    '#tlbb_wulaoda:die': '虚竹宫主宅心仁厚，小人愿誓死相从……<br><br><br>',
    '#tlbb_xiaoyao1': '逍遥堪自乐，浩荡信无忧。',
