    '#tlbb_minghai3': '无穷般若心自在，语默动静体自然。',
    '#tlbb_minghai4': '大乘寂灭时，幻海现佛宗。',
    '#tlbb_jue_xuzhu:die': '众生皆苦，有缘皆孽……<br><br><br>',
