    '#tlbb_chunhui2': '孤鸿号外野，翔鸟鸣北林！',
    '#tlbb_yuanmeng1': '相见时稀隔别多，又春尽，奈悉何！',
    '#tlbb_yuanmeng2': '段郎，你可知我多年对你魂牵梦萦？',
    '#tlbb_ruanxingzhu:die': '旧梦重温，虽死无憾……<br><br><br>',
