    '#sdxl_liufang2': '生死两茫茫，何处话凄凉？',
    '#sdxl_xiaohun1': '断肠之殇，锥心之痛！！',
    '#sdxl_xiaohun2': '黯然销魂者，唯别而已矣！',
    '#sdxl_spyangguo:die': '古墓，是我们最好的归宿……<br><br><br>',
