    '#xajh_weishan2': '知者不惑，仁者不忧。<br>义人纵渴，不饮盗泉之水！<br>信义行于君子，而诡诈施于小人。<br>武林相逢，我辈当以礼为先。<br>明礼而知进退，自省而全得失。',
    '#xajh_koumi1': '你我师徒恩义已断，毋宁多言！',
    '#xajh_koumi2': '正邪不两立，休怪岳某手下无情！',
